#include "MusicalComparison.h"
#include "SelectionPreview.h"
#include <iostream>
#include <stdexcept>
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
int main(){try{std::atomic<bool> cancel{false};nova::Sound source;source.sampleRate=16000;source.left.resize(64000);source.right=source.left;std::vector<nova::ContextNote> notes;int pitches[]={60,64,67};for(int j=0;j<3;++j){nova::ContextNote note;note.note=pitches[j];note.range={j+ .2,j+.8};note.velocity=.4f+j*.2f;note.confidence=1;notes.push_back(note);double hz=440*std::pow(2.,(note.note-69)/12.);for(size_t i=static_cast<size_t>(note.range.start*16000);i<static_cast<size_t>(note.range.end*16000);++i)source.left[i]=source.right[i]=.2f*std::sin(2*nova::pi*hz*(i/16000.-note.range.start));}
 nova::Params p;p.engine=0;p.waveA=p.waveB=0;p.mix=p.sub=p.noise=p.fm=p.detune=p.fineTune=p.lfoDepth=p.delay=p.reverb=p.chorus=p.drive=0;p.unison=false;p.cutoff=19000;p.envAmount=0;p.attack=.001f;p.release=.01f;p.sustain=1;float last=0;auto result=nova::compareSequence(source,notes,p,nullptr,nullptr,true,cancel,[&](float progress){check(progress>=last&&progress<=1,"monotonic progress");last=progress;});check(result.valid&&result.events==3&&result.measured==3&&result.pitchMeasured==3&&result.maxPitchCents<1.5,"three MIDI events rendered and measured at correct pitch");check(result.recreated.left.size()==source.left.size()&&last==1,"same duration and complete progress");for(int i=0;i<3100;++i)check(std::abs(result.recreated.left[i])<1e-7,"initial silence and first onset preserved");check(std::abs(nova::soundRms(result.original)-nova::soundRms(result.recreated))<.01,"matched audition levels");check(source.left[5000]!=result.original.left[5000],"level matching uses a comparison copy");
 auto analysed=nova::analyseContext(source,cancel);check(analysed.sequence.size()==3,"full event sequence distinct from learning windows");nova::Sound sustained=source;sustained.left.resize(16000*8);sustained.right=sustained.left;for(size_t i=0;i<sustained.left.size();++i)sustained.left[i]=sustained.right[i]=.2f*std::sin(2*nova::pi*440*i/16000.);auto longNote=nova::analyseContext(sustained,cancel);check(longNote.sequence.size()==1&&longNote.sequence[0].range.length()>7,"long sustain is one event, not three candidate windows");
 nova::SelectionPreview transport;auto shared=std::make_shared<nova::Sound>(result.recreated);std::weak_ptr<const nova::Sound> weak=shared;auto clip=std::make_unique<nova::SelectionPreview::Clip>();clip->sharedSound=shared;clip->generation=transport.stop();transport.publish(std::move(clip));shared.reset();check(!weak.expired(),"shared audition owns ephemeral comparison audio");std::array<float,512> l{},r{};transport.render(l.data(),r.data(),512,48000);check(transport.playing.load(),"shared clip transport starts");transport.stop();transport.render(l.data(),r.data(),512,48000);check(!transport.playing.load(),"shared clip stops by generation");
 cancel.store(true);check(nova::compareSequence(source,notes,p,nullptr,nullptr,false,cancel).cancelled,"comparison cancellation");cancel.store(false);check(!nova::compareSequence(source,{},p,nullptr,nullptr,false,cancel).valid,"empty sequence rejected");std::cout<<"PASS: sequence timing/silence, three pitches and velocities, duration, RMS, complete sustained event, shared preview lifetime, cancellation and empty rejection\n";
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
